const events = [
 {id:'desert',title:'Desert Frequencies',subtitle:'A night of psych rock & high desert sound.',category:'Music',genre:'PSYCH ROCK / LIVE',city:'Albuquerque',venue:'Sister',date:23,day:'FRI',time:'8:00 PM',price:18,age:'21+',going:64,interested:128,color:'#e8bd68',description:'Fuzzed-out guitars, slow-burning grooves, and the kind of set that makes you forget to check your phone. Three fictional New Mexico bands turn a small room into a very big night.',expect:'An intimate standing-room show, a full bar, and a crowd that came to listen. Doors at 7 PM; the first band takes the stage at 8.',tip:'Make a night of downtown. Grab a bite first, then arrive early for a spot close to the stage.',address:'Downtown · Albuquerque',lineup:'Mesa Static · The Low Suns · Coyote Radio'},
 {id:'laughs',title:'The Late Set',subtitle:'Sharp jokes. Small room. No two-drink minimum.',category:'Comedy',genre:'STAND-UP / LATE NIGHT',city:'Albuquerque',venue:'Dry Heat Comedy Club',date:23,day:'FRI',time:'9:30 PM',price:15,age:'21+',going:38,interested:72,color:'#d3c4d9',description:'A loose, late-night lineup of local comics working out very good material and occasionally very bad life choices. Come for the headliner. Stay for the surprise drop-in.',expect:'A seated, 90-minute showcase with a host and four comics. Seating is first come, first served. This fictional lineup contains adult material.',tip:'Arrive 20 minutes before the show to get settled. The front row comes with a certain amount of responsibility.',address:'Nob Hill · Albuquerque',lineup:'Four local voices. One very late set.'},
 {id:'jazz',title:'Blue Hour, Santa Fe',subtitle:'An intimate evening of jazz, without a rush.',category:'Music',genre:'JAZZ / QUARTET',city:'Santa Fe',venue:'The High Desert Room',date:24,day:'SAT',time:'7:00 PM',price:25,age:'21+',going:42,interested:96,color:'#afc4c0',description:'Upright bass, brushed drums, and a piano that knows when to leave a little space. A fictional quartet brings warm standards and a few unexpected arrangements to an intimate Santa Fe listening room.',expect:'Two unhurried sets with a short intermission. Table seating, cocktails, and a room built around the music.',tip:'Leave time for an early dinner. This is a listening room, so save the long catch-up for the intermission.',address:'Railyard district · Santa Fe',lineup:'The Blue Hour Quartet'},
 {id:'print',title:'Ink After Dark',subtitle:'Printmaking, natural wine, and a little creative mess.',category:'Culture',genre:'WORKSHOP / SOCIAL',city:'Albuquerque',venue:'Barelas Print Studio',date:24,day:'SAT',time:'6:00 PM',price:32,age:'21+',going:19,interested:51,color:'#c4c9a4',description:'Trade another night of scrolling for ink on your hands. Learn the basics of block printing in a relaxed, fictional neighborhood studio session, then make something imperfect and entirely yours.',expect:'A two-hour guided workshop with tools, materials, and one wine or alcohol-free pour included. No experience needed. Take home your prints.',tip:'Wear something you would happily get ink on. Solo visitors are very welcome; everyone shares a worktable.',address:'Barelas · Albuquerque',lineup:'A small-group evening at the worktable.'},
 {id:'vinyl',title:'Sunday, On the Record',subtitle:'Rare grooves and one more reason to stay a while.',category:'Music',genre:'VINYL / LISTENING SESSION',city:'Taos',venue:'The Adobe Lounge',date:25,day:'SUN',time:'4:00 PM',price:0,age:'21+',going:31,interested:88,color:'#d8b59f',description:'A slow Sunday soundtracked by soul, dusty jazz, and records worth turning over. Local selectors share the stories behind their favorite finds in this fictional afternoon listening session.',expect:'An easygoing drop-in gathering. No cover, no dance-floor obligations. Drinks available at the bar; come and go between sides.',tip:'Bring a record with a story. The final hour opens up to a few selections from the room.',address:'Historic center · Taos',lineup:'Resident selectors + records from the room'}
];
let saved;try{saved=new Set(JSON.parse(localStorage.getItem('burque-saved')||'[]'))}catch{saved=new Set()}
let category='All', savedOnly=false,active=null,busy=false,audioContext=null,audioTimer=null,playing=false;
const $=s=>document.querySelector(s), dialog=$('#event-dialog'), money=e=>e.price?'$'+e.price:'Free';
function persist(){try{localStorage.setItem('burque-saved',JSON.stringify([...saved]))}catch{}$('#saved-count').textContent=saved.size}
function render(){let list=events.filter(e=>(category==='All'||e.category===category)&&($('#city').value==='All'||e.city===$('#city').value)&&(!savedOnly||saved.has(e.id)));$('#results-count').textContent=String(list.length).padStart(2,'0')+' GOOD REASONS TO GO OUT';$('#events').innerHTML=list.length?list.map(e=>`<article class="event-card" data-id="${e.id}"><button class="event-open" aria-label="View ${e.title}"></button><div class="date-block"><span class="day">${e.day}</span><span class="number">${e.date}</span><span class="month">OCT</span></div><div class="card-body"><div class="category-line"><span>${e.genre}</span><span class="age">${e.age}</span></div><h2 class="card-title" data-shared="title">${e.title}</h2><div class="venue" data-shared="venue">${e.venue} <span> / ${e.city}</span></div><div class="card-bottom"><div class="time-price"><span data-shared="time">${e.time}</span><span data-shared="price">${money(e)}</span></div><span class="discover">Make a night of it ↗</span></div></div><button class="save ${saved.has(e.id)?'selected':''}" aria-label="${saved.has(e.id)?'Unsave':'Save'} ${e.title}" aria-pressed="${saved.has(e.id)}">${saved.has(e.id)?'◆':'◇'}</button></article>`).join(''):'<div class="empty">No nights here yet. Try another city or category.</div>';persist()}
function toggleSave(id){saved.has(id)?saved.delete(id):saved.add(id);persist();render()}
function assignShared(container,on){container.querySelectorAll('[data-shared]').forEach(el=>el.style.viewTransitionName=on?'event-'+el.dataset.shared:'')}
async function transition(change){busy=true;try{if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches){let t=document.startViewTransition(change);await t.finished}else change()}catch{}finally{busy=false}}
function detailMarkup(e){const music=e.category==='Music';return `<div class="detail-shell" style="--detail-bg:${e.color}"><header class="detail-top"><button class="back" id="close-detail">← Back to the good stuff</button><span class="eyebrow">BURQUE / YOUR NIGHT, CONSIDERED.</span><span class="wordmark">b<span>✳</span></span></header><pre class="ascii" aria-hidden="true">     \\  |  /       \\  |  /       \\  |  /
      \\ | /         \\ | /         \\ | /
  _____\\|/___________\\|/___________\\|/____
  |        .      .       .      .         |
  |    /|  |\\   /|   |\\  |\\   /|   |\\     |
  |___/ |__| \\_/ |___| \\_| \\_/ |___| \\____|
    o   o   o   o   o   o   o   o   o
   /|\\ /|\\ /|\\ /|\\ /|\\ /|\\ /|\\ /|\\ /|\\
   / \\ / \\ / \\ / \\ / \\ / \\ / \\ / \\ / \\</pre><div class="detail-layout"><article><div class="detail-kicker"><span>${e.genre}</span><span>${e.age} / ${e.city.toUpperCase()}</span></div><h1 class="detail-title" id="detail-title" data-shared="title">${e.title}</h1><div class="detail-venue" data-shared="venue">${e.venue} / ${e.city}</div><div class="detail-meta"><div class="meta-item"><span class="label">THE DATE</span><span>${e.day==='FRI'?'Friday':e.day==='SAT'?'Saturday':'Sunday'}, October ${e.date}</span></div><div class="meta-item"><span class="label">THE TIME</span><span data-shared="time">${e.time}</span></div><div class="meta-item"><span class="label">THE PLACE</span><span>${e.city}, NM</span></div></div><div class="detail-copy"><p>${e.description}</p><h2>The shape of the night</h2><p>${e.expect}</p><p><strong>${e.lineup}</strong></p><div class="local-tip"><span class="label">A LITTLE LOCAL KNOW-HOW</span><p>${e.tip}</p></div></div></article><aside class="detail-aside"><div class="experience" aria-hidden="true">${music?'<div class="record"></div>':`<div class="specimen">${e.category==='Comedy'?'ha.':'ink.'}</div>`}</div><div class="ambience-controls">${music?'<button id="ambience" class="ambient-button"><span>▶ Play a little atmosphere</span><span>♪</span></button><p class="aside-note">An original synthesized mood loop.<br>A taste of the vibe, not the actual artist.</p>':'<p class="aside-note">A different kind of night.<br>Same room for a little discovery.</p>'}</div><div class="ticket-panel"><span class="label">YOUR WAY IN</span><div class="ticket-price"><span data-shared="price">${money(e)}</span> <small>${e.price?' / person':''}</small></div><span class="ticket-caption">${e.price?'Demo price · fees not included':'No cover. Just good company.'}</span><button class="primary-button" id="ticket">${e.price?'Ticket details':'Plan your visit'}<span>↗</span></button><button id="interest" class="interest-button" aria-pressed="${saved.has(e.id)}">${saved.has(e.id)?'✓ Saved to your nights':'◇ I’m interested'}</button><p class="social-proof">${e.going} going · ${e.interested} interested<br>Fictional crowd, very real potential.</p></div></aside></div><div class="detail-foot"><span>${e.address.toUpperCase()}</span><span>CURATED WITH INTENTION. / DEMO EVENT</span></div></div>`}
async function openEvent(id){if(busy)return;active=id;const e=events.find(x=>x.id===id),card=document.querySelector(`[data-id="${id}"]`);assignShared(card,true);await transition(()=>{assignShared(card,false);$('#detail').innerHTML=detailMarkup(e);dialog.appendChild(document.getElementById("toast"));dialog.showModal();dialog.scrollTop=0;document.body.style.overflow='hidden';assignShared($('#detail'),true)});$('#close-detail').focus({preventScroll:true})}
async function closeEvent(){if(busy||!dialog.open)return;stopAudio();await transition(()=>{assignShared($('#detail'),false);dialog.close();document.body.appendChild(document.getElementById('toast'));document.body.style.overflow='';const card=document.querySelector(`[data-id="${active}"]`);if(card)assignShared(card,true)});const card=document.querySelector(`[data-id="${active}"]`);if(card){assignShared(card,false);card.querySelector('.event-open').focus({preventScroll:true})}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
function stopAudio(){playing=false;clearInterval(audioTimer);if(audioContext){audioContext.close();audioContext=null}$('.experience')?.classList.remove('playing');const b=$('#ambience');if(b){b.firstElementChild.textContent='▶ Play a little atmosphere';b.setAttribute('aria-pressed','false')}}
async function startAudio(){if(playing){stopAudio();return}const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio){toast('Audio preview is unavailable in this browser.');return}audioContext=new Audio();await audioContext.resume();playing=true;$('.experience').classList.add('playing');$('#ambience').firstElementChild.textContent='Ⅱ Pause atmosphere';$('#ambience').setAttribute('aria-pressed','true');const jazz=active==='jazz',notes=jazz?[130.81,164.81,196,246.94,220,196,164.81,146.83]:[82.41,82.41,123.47,110,98,98,123.47,110];let i=0;const play=()=>{if(!audioContext)return;let t=audioContext.currentTime;const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.type=jazz?'sine':'triangle';osc.frequency.value=notes[i++%notes.length];gain.gain.setValueAtTime(0,t);gain.gain.linearRampToValueAtTime(.065,t+.03);gain.gain.exponentialRampToValueAtTime(.001,t+.5);osc.connect(gain).connect(audioContext.destination);osc.start(t);osc.stop(t+.55)};play();audioTimer=setInterval(play,jazz?440:280)}
$('#events').addEventListener('click',e=>{const card=e.target.closest('.event-card');if(!card)return;if(e.target.closest('.save'))toggleSave(card.dataset.id);else if(e.target.closest('.event-open'))openEvent(card.dataset.id)});
document.querySelectorAll('.chip').forEach(b=>b.addEventListener('click',()=>{category=b.dataset.category;document.querySelectorAll('.chip').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});render()}));$('#city').addEventListener('change',render);$('#saved-filter').addEventListener('click',()=>{savedOnly=!savedOnly;$('#saved-filter').firstChild.textContent=savedOnly?'All events ':'Saved ';$('#saved-filter').setAttribute('aria-pressed',savedOnly);render()});
dialog.addEventListener('cancel',e=>{e.preventDefault();closeEvent()});dialog.addEventListener('click',e=>{if(e.target.closest('#close-detail'))closeEvent();if(e.target.closest('#ambience'))startAudio();if(e.target.closest('#interest')){toggleSave(active);const b=$('#interest');b.textContent=saved.has(active)?'✓ Saved to your nights':'◇ I’m interested';b.setAttribute('aria-pressed',saved.has(active))}if(e.target.closest('#ticket'))toast('This is a fictional event. Ticket booking will connect here in the real site.')});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio()});render();

